import{_ as e,o as a,c as i,a4 as o}from"./chunks/framework.DzALyu-k.js";const h=JSON.parse('{"title":"Advanced · GitHub Harness","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/github-harness/index.md","filePath":"advanced/github-harness/index.md"}'),r={name:"advanced/github-harness/index.md"};function n(d,t,s,l,c,u){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="advanced-·-github-harness" tabindex="-1">Advanced · GitHub Harness <a class="header-anchor" href="#advanced-·-github-harness" aria-label="Permalink to &quot;Advanced · GitHub Harness&quot;">​</a></h1><p>Il caso pratico costruito con la <strong>GitHub Copilot harness</strong>: l&#39;Agente Demand IT, con istruzioni, skill, Dataverse MCP Server e workflow, riceve, valuta e prepara per il Comitato le proposte di progetto IT di Zava. La storia del caso e gli schemi dei componenti si trovano nei laboratori, a partire dal <a href="./00-setup-dati/">Lab 00</a>.</p><h2 id="lab" tabindex="-1"><span class="icon f-instructions"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M208,216H48a8,8,0,0,1-6.86-12.12l30.48-50.8h0c13.23-2.48,32-1.41,56.37,10.92,32.25,16.33,54.75,12.91,67.5,7.65h0l19.34,32.23A8,8,0,0,1,208,216Z" opacity="0.2"></path><path d="M221.69,199.77,160,96.92V40h8a8,8,0,0,0,0-16H88a8,8,0,0,0,0,16h8V96.92L34.31,199.77A16,16,0,0,0,48,224H208a16,16,0,0,0,13.72-24.23ZM110.86,103.25A7.93,7.93,0,0,0,112,99.14V40h32V99.14a7.93,7.93,0,0,0,1.14,4.11L183.36,167c-12,2.37-29.07,1.37-51.75-10.11-15.91-8.05-31.05-12.32-45.22-12.81ZM48,208l28.54-47.58c14.25-1.73,30.31,1.85,47.82,10.72,19,9.61,35,12.88,48,12.88a69.89,69.89,0,0,0,19.55-2.7L208,208Z"></path></svg></span> Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;&lt;span class=&quot;icon f-instructions&quot;&gt;&lt;svg aria-hidden=&quot;true&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot; viewBox=&quot;0 0 256 256&quot; fill=&quot;currentColor&quot;&gt;&lt;path d=&quot;M208,216H48a8,8,0,0,1-6.86-12.12l30.48-50.8h0c13.23-2.48,32-1.41,56.37,10.92,32.25,16.33,54.75,12.91,67.5,7.65h0l19.34,32.23A8,8,0,0,1,208,216Z&quot; opacity=&quot;0.2&quot;/&gt;&lt;path d=&quot;M221.69,199.77,160,96.92V40h8a8,8,0,0,0,0-16H88a8,8,0,0,0,0,16h8V96.92L34.31,199.77A16,16,0,0,0,48,224H208a16,16,0,0,0,13.72-24.23ZM110.86,103.25A7.93,7.93,0,0,0,112,99.14V40h32V99.14a7.93,7.93,0,0,0,1.14,4.11L183.36,167c-12,2.37-29.07,1.37-51.75-10.11-15.91-8.05-31.05-12.32-45.22-12.81ZM48,208l28.54-47.58c14.25-1.73,30.31,1.85,47.82,10.72,19,9.61,35,12.88,48,12.88a69.89,69.89,0,0,0,19.55-2.7L208,208Z&quot;/&gt;&lt;/svg&gt;&lt;/span&gt; Lab&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lab</th><th>Titolo</th><th>Che cosa impari</th><th>Tempo</th></tr></thead><tbody><tr><td><a href="./00-setup-dati/">00</a></td><td>Setup dati</td><td>Import della soluzione pronta, modello dati Dataverse, app PMO Demand Hub e dati di partenza</td><td>45 min</td></tr><tr><td><a href="./01-agente-orchestratore/">G01</a></td><td>Agente orchestratore</td><td>Identità bloccata al primo salvataggio, istruzioni come contratto</td><td>30 min</td></tr><tr><td><a href="./02-istruzioni-skill-e-dataverse-mcp/">G02</a></td><td>Istruzioni, skill e Dataverse MCP</td><td>Skill da zero, server MCP con privilegi minimi, Preview, valutazione di base</td><td>75 min</td></tr><tr><td><a href="./03-agente-connesso/">G03</a></td><td>Agente connesso</td><td>Specialista in sola lettura, autenticazione Maker, delega</td><td>60 min</td></tr><tr><td><a href="./04-modello-risposta-e-sicurezza/">G04</a></td><td>Modello, risposta e sicurezza</td><td>Disclosure, guardrail, valutazione di sicurezza da CSV, injection</td><td>35 min</td></tr><tr><td><a href="./05-intake-valutazione-registrazione/">G05</a></td><td>Intake, valutazione e registrazione</td><td>Lettura nativa di PDF e DOCX, rubrica, scritture dopo conferma</td><td>90 min</td></tr><tr><td><a href="./06-dossier-skill-python/">G06</a></td><td>Dossier di revisione con una skill Python</td><td>Skill importata da zip, script <code>python-docx</code>, layout definito nel codice, validazione</td><td>45 min</td></tr><tr><td><a href="./07-workflow-trigger-email/">G07</a></td><td>Workflow di intake con trigger email</td><td>Trigger agente provato e rimosso, workflow con Classify, Scope, loop sugli allegati, registrazione in Dataverse</td><td>105 min</td></tr><tr><td><a href="./08-agenti-nel-workflow/">G08</a></td><td>Agenti nel workflow</td><td>Agente inline e agente pubblicato come nodi, scheda adattiva nel canale Proposte</td><td>90 min</td></tr><tr><td><a href="./09-supervisione-umana/">G09</a></td><td>Supervisione umana ed errori</td><td>Human review, rami chiusi con End, try/catch con avviso in Teams, errore provocato</td><td>75 min</td></tr><tr><td><a href="./10-pianificazione-revisione/">G10</a></td><td>Fissare la revisione: via libera e agente di pianificazione</td><td>Workflow come strumento con soglia e Approvals, agente connesso con Office 365 Users e Outlook, conferma prima dell&#39;invito</td><td>90 min</td></tr><tr><td><a href="./11-evaluate-pubblicazione-monitor/">G11</a></td><td>Rilascio: memoria, Teams e monitoraggio</td><td>Memory, pubblicazione in Teams, condivisione, Monitor e reazioni</td><td>40 min</td></tr></tbody></table><h2 id="prerequisiti-specifici" tabindex="-1">Prerequisiti specifici <a class="header-anchor" href="#prerequisiti-specifici" aria-label="Permalink to &quot;Prerequisiti specifici&quot;">​</a></h2><p>Oltre ai prerequisiti del <a href="./00-setup-dati/">Lab 00</a>, questo percorso richiede:</p><ul><li>licenze per i connettori Office 365 Outlook, Office 365 Users, Microsoft Teams e OneDrive for Business nel tenant di laboratorio;</li><li>per il Lab G10, un secondo utente del tenant, con casella di posta, da usare come sponsor o architetto nei test di pianificazione: tutti i partecipanti alle riunioni devono essere <strong>interni</strong> al tenant;</li><li>Microsoft Dataverse MCP Server disponibile nell&#39;ambiente, licenza Microsoft 365 con Exchange Online per i calendari (Lab G10) e capacità di Copilot Credits.</li></ul>',7)])])}const m=e(r,[["render",n]]);export{h as __pageData,m as default};
